// Great Uniqorn — sound event catalogue (engine: js/sound-kit.js, shared with
// the dev sound panel ♪ of js/dev-tools.js).
//
// 2026-11-23: variants A..E of the music and every game sound are 5 whole
// SETS in one genre each (sound/great-uniqorn/sets/, generated by
// scripts/great_uniqorn_sound_sets.py), switched together by the «Звуковой
// сет» chips in ♪; the composer's pack is F. F is the default, with the
// sound designer's volumes (2026-11-24).
//
// v01 of every event is the composer's pack ("Great Uniqorn SFX (Short)",
// 2026-11-11); v02, where there is one, is the earlier synthesized take
// (sound/great-uniqorn/synth_v1/, scripts/great_uniqorn_audio.py) kept to
// compare in the panel. The pack has no reel stops or bonus enter/exit, so
// those are the synthesized ones. A choice made in ♪ (variant, volume, mute)
// is stored per game in localStorage ('soundlab.great-uniqorn') and applies
// both here in the slot and on the animations pages.
//
// Event keys follow the shared spin order (js/slot-flow.js): scatterLand1..3,
// anticipation (loop) + anticipationWin/Fail, winLine, symWin_<code>,
// countLoop/countEnd, baseToBonus/bonusToBase. Events with no file of this
// game yet stay listed in ♪ as «нет звука».
// The API the slot uses: playSfx(name), playMusic('base'|'bonus'),
// startLoop(name) -> stop(), toggleMuted(), muted, preloadPromises.
// On top of SoundKit: each music level also runs its ambience bed (the
// AMBIENT_* loop) underneath, switched together with the music.
(function () {
  const GAME = 'sound/great-uniqorn/';
  const OLD = `${GAME}synth_v1/`;
  // 2026-11-23: the composer's quieter re-export of the wins + music (v01);
  // the first, louder export stays as a variant to compare in ♪.
  const LOUD = `${GAME}pack_loud/`;
  const QUIET = '?p=2';
  const v = (...files) => files.filter(Boolean);
  // 2026-11-27: music made in Suno, one track at a time with the user
  // (bar-aligned seamless loops cut by scratchpad loopfind/render_loop; lossless FLAC
  // so <audio loop> has no gap at the seam). The default for base/bonus.
  const SUNO = `${GAME}suno/`;

  const EVENTS = {
    base: { kind: 'music', group: 'Музыка', label: 'Музыка — база', src: v(`${GAME}MUSIC_Base.mp3${QUIET}`, `${LOUD}MUSIC_Base.mp3`, `${OLD}BG_Base.mp3`) },
    bonus: { kind: 'music', group: 'Музыка', label: 'Музыка — фриспины', src: v(`${GAME}MUSIC_Bonus.mp3${QUIET}`, `${LOUD}MUSIC_Bonus.mp3`, `${OLD}BG_Bonus.mp3`) },
    intro: { group: 'Музыка', label: 'Заставка (первый клик, потом музыка базы)', src: v(`${SUNO}intro.mp3?p=1`) },
    ambientBase: { group: 'Музыка', label: 'Эмбиент — база (под музыкой)', src: v(`${GAME}AMBIENT_Base.mp3`), loop: true, volume: 0.25 },
    ambientBonus: { group: 'Музыка', label: 'Эмбиент — фриспины (под музыкой)', src: v(`${GAME}AMBIENT_Bonus.mp3`), loop: true, volume: 0.25 },

    smallWin: { group: 'Выигрыши', label: 'Выигрыш по линии', src: v(`${GAME}WIN_Line.mp3${QUIET}`, `${LOUD}WIN_Line.mp3`, `${OLD}WIN_Line.mp3`) },
    bigWin: { group: 'Выигрыши', label: 'BIG WIN', src: v(`${GAME}WIN_Bigwin.mp3${QUIET}`, `${LOUD}WIN_Bigwin.mp3`, `${OLD}WIN_Big.mp3`) },
    megaWin: { group: 'Выигрыши', label: 'MEGA WIN', src: v(`${GAME}WIN_Megawin.mp3${QUIET}`, `${LOUD}WIN_Megawin.mp3`, `${OLD}WIN_Mega.mp3`) },
    epicWin: { group: 'Выигрыши', label: 'EPIC WIN', src: v(`${GAME}WIN_Epicwin.mp3${QUIET}`, `${LOUD}WIN_Epicwin.mp3`, `${OLD}WIN_Epic.mp3`) },
    fsWin: { group: 'Выигрыши', label: 'FS WIN — выпали фриспины (попап)', src: [], off: true },
    fsRetrigger: { group: 'Выигрыши', label: 'Ретриггер — +фриспины в бонусе (попап)', src: [], off: true },
    bonusTotalWin: { group: 'Выигрыши', label: 'BONUS SPINS TOTAL WIN', src: v(`${GAME}WIN_Bigwin.mp3${QUIET}`, `${LOUD}WIN_Bigwin.mp3`, `${OLD}WIN_Big.mp3`), note: 'у композитора своей дорожки нет — как BIG WIN; у Suno своя' },
    winLine: { group: 'Выигрыши', label: 'Линия в показе выигрыша (каждая по очереди)', src: v(`${GAME}WIN_Line.mp3${QUIET}`, `${LOUD}WIN_Line.mp3`, `${OLD}WIN_Line.mp3`) },
    countLoop: { group: 'Выигрыши', label: 'Счётчик суммы (петля)', src: v(`${GAME}WIN_Cashloop.mp3${QUIET}`, `${LOUD}WIN_Cashloop.mp3`, `${OLD}WIN_CashLoop.mp3`), loop: true },
    countEnd: { group: 'Выигрыши', label: 'Счётчик суммы — конец' },

    scatterLand1: { group: 'Символы', label: 'Скаттер — 1-й бургер упал', src: v(`${GAME}SCATTER_1.mp3`, `${OLD}SCATTER_1.mp3`) },
    scatterLand2: { group: 'Символы', label: 'Скаттер — 2-й бургер упал', src: v(`${GAME}SCATTER_2.mp3`, `${OLD}SCATTER_2.mp3`) },
    scatterLand3: { group: 'Символы', label: 'Скаттер — 3-й и дальше', src: v(`${GAME}SCATTER_3.mp3`, `${OLD}SCATTER_3.mp3`) },
    // a symbol's melody under its first win pass (js/slot-flow.js presentWins)
    symWin_scatter: { group: 'Мелодии символов', label: 'Скаттер — выигрыш / запуск бонуса', src: v(`${GAME}SCATTER_Win.mp3`, `${OLD}SCATTER_Win.mp3`) },
    symWin_wild: { group: 'Мелодии символов', label: 'Wild' },
    symWin_jet: { group: 'Мелодии символов', label: 'Самолёт' },
    symWin_docs: { group: 'Мелодии символов', label: 'Документы' },
    symWin_hair: { group: 'Мелодии символов', label: 'Причёска' },
    symWin_a: { group: 'Мелодии символов', label: 'A' },
    symWin_k: { group: 'Мелодии символов', label: 'K' },
    symWin_q: { group: 'Мелодии символов', label: 'Q' },
    symWin_j: { group: 'Мелодии символов', label: 'J' },
    wildLand: { group: 'Символы', label: 'Wild упал на барабан', src: v(`${GAME}WILD_Land.mp3`) },
    wildGrow: { group: 'Символы', label: 'Wild → множитель', src: v(`${GAME}WILD_Multiplier.mp3`, `${OLD}WILD_Multiplier.mp3`) },

    baseToBonus: { group: 'Бонус', label: 'Вход в фриспины (затемнение)', src: v(`${GAME}BONUS_Enter.mp3`) },
    bonusToBase: { group: 'Бонус', label: 'Выход из фриспинов', src: v(`${GAME}BONUS_Exit.mp3`) },
    buyButton: { group: 'Бонус', label: 'Покупка — окно открылось', src: v(`${GAME}BUY_Button.mp3`) },
    buyConfirm: { group: 'Бонус', label: 'Покупка — BUY', src: v(`${GAME}BUY_Confirm.mp3`) },

    click: { group: 'Интерфейс', label: 'Клик', src: v(`${GAME}UI_Click.mp3`, `${OLD}UI_Click.mp3`) },
    popupOpen: { group: 'Интерфейс', label: 'Попап открылся', src: v(`${GAME}UI_Popupopen.mp3`, `${OLD}UI_PopupOpen.mp3`) },
    popupClose: { group: 'Интерфейс', label: 'Попап закрылся', src: v(`${GAME}UI_Popupclose.mp3`, `${OLD}UI_PopupClose.mp3`) },
    autospin: { group: 'Интерфейс', label: 'Автоспин', src: v(`${GAME}UI_Autospin.mp3`, `${OLD}UI_Autospin.mp3`) },
    betPlus: { group: 'Интерфейс', label: 'Ставка +', src: v(`${GAME}UI_Betplus.mp3`, `${OLD}UI_BetPlus.mp3`) },
    betMinus: { group: 'Интерфейс', label: 'Ставка −', src: v(`${GAME}UI_Betminus.mp3`, `${OLD}UI_BetMinus.mp3`) },
    menu: { group: 'Интерфейс', label: 'Меню', src: v(`${GAME}UI_Menu.mp3`, `${OLD}UI_Menu.mp3`) },
    turbo: { group: 'Интерфейс', label: 'Турбо', src: v(`${GAME}UI_Turbo.mp3`, `${OLD}UI_Turbo.mp3`) },

    // reels 1-4 stop on rising notes (a little melody per spin), the 5th resolves
    spinStart: { group: 'Барабаны', label: 'Старт спина', src: v(`${GAME}REEL_SpinStart.mp3`) },
    reelStop1: { group: 'Барабаны', label: 'Стоп барабана 1', src: v(`${GAME}REEL_Stop_1.mp3`) },
    reelStop2: { group: 'Барабаны', label: 'Стоп барабана 2', src: v(`${GAME}REEL_Stop_2.mp3`) },
    reelStop3: { group: 'Барабаны', label: 'Стоп барабана 3', src: v(`${GAME}REEL_Stop_3.mp3`) },
    reelStop4: { group: 'Барабаны', label: 'Стоп барабана 4', src: v(`${GAME}REEL_Stop_4.mp3`) },
    finalReelStop: { group: 'Барабаны', label: 'Стоп последнего барабана', src: v(`${GAME}REEL_StopLast.mp3`) },
    anticipation: { group: 'Барабаны', label: 'Антисипация (петля до стопа барабана)', src: v(`${GAME}REEL_Anticipation.mp3`), loop: true },
    anticipationWin: { group: 'Барабаны', label: 'Антисипация — удача' },
    anticipationFail: { group: 'Барабаны', label: 'Антисипация — неудача' },
  };

  // --- 5 whole sound sets (scripts/great_uniqorn_sound_sets.py) ------------
  // Every set is one GENRE for the music AND every game sound below; they are
  // variants A..E of each event, the composer's pack is F, so one chip in ♪
  // switches the lot. UI clicks are shared (not in the sets).
  const SETS = `${GAME}sets/`;
  const SET_NAMES = { march: 'Президентский марш', jazz: 'Джаз Овального кабинета', funk: 'Фанк-кампания', synthwave: 'Синтвейв-Вашингтон', disco: 'Диско-гала' };
  const SET_KEYS = Object.keys(SET_NAMES);
  const SET_LOOPS = new Set(['countLoop', 'anticipation']); // gapless wav
  const SET_EVENTS = ['base', 'bonus', 'smallWin', 'winLine', 'bigWin', 'megaWin', 'epicWin', 'bonusTotalWin', 'countLoop', 'countEnd',
    'scatterLand1', 'scatterLand2', 'scatterLand3', 'symWin_scatter', 'wildLand', 'wildGrow', 'baseToBonus', 'bonusToBase',
    'buyButton', 'buyConfirm', 'spinStart', 'reelStop1', 'reelStop2', 'reelStop3', 'reelStop4', 'finalReelStop',
    'anticipation', 'anticipationWin', 'anticipationFail'];
  for (const key of SET_EVENTS) {
    const e = EVENTS[key];
    const ext = SET_LOOPS.has(key) ? 'wav' : 'mp3';
    // default = the composer's pack (the sound designer's pick, 2026-11-24);
    // events the pack has no file for stay silent until a set is chosen
    if (e.src && e.src.length) e.variant = e.src[0]; else e.off = true;
    e.src = [...SET_KEYS.map((k) => `${SETS}${k}/${key}.${ext}?p=1`), ...(e.src || [])];
  }

  // --- the sound designer's mix (♪ export «звуки.txt», 2026-11-24) ---------
  const DESIGNER_VOLUME = {
    base: 0.57, bonus: 0.87, ambientBase: 0.26, ambientBonus: 0.31,
    baseToBonus: 0.6, bonusToBase: 0.61, buyButton: 0.78, buyConfirm: 0.74,
    click: 0.29, popupOpen: 1.12, betPlus: 0.59, betMinus: 0.61, menu: 0.43, turbo: 0.8,
    reelStop1: 0.25, reelStop2: 0.52, reelStop3: 0.79, reelStop4: 1.06, finalReelStop: 1.25,
  };
  for (const [key, vol] of Object.entries(DESIGNER_VOLUME)) EVENTS[key].volume = vol;

  // Suno music: last variant of base/bonus, and the default to try it
  EVENTS.base.src.push(`${SUNO}base_loop.flac?p=1`);
  EVENTS.bonus.src.push(`${SUNO}bonus_loop.flac?p=1`);
  EVENTS.base.variant = `${SUNO}base_loop.flac?p=1`;
  EVENTS.bonus.variant = `${SUNO}bonus_loop.flac?p=1`;
  // Suno stingers (Sounds tab), one at a time: the last variant + the default
  // (several takes of one event = several variants, the first is the default)
  const SUNO_SFX = {
    baseToBonus: ['bonus_enter.mp3'],
    bonusToBase: ['bonus_exit_1.mp3', 'bonus_exit_2.mp3'],
    bigWin: ['big_win_1.mp3', 'big_win_2.mp3'],
    megaWin: ['mega_win_1.mp3', 'mega_win_2.mp3'],
    epicWin: ['epic_win_1.mp3', 'epic_win_2.mp3'],
    fsWin: ['fs_win_1.mp3', 'fs_win_2.mp3'],
    fsRetrigger: ['fs_retrigger_1.mp3', 'fs_retrigger_2.mp3'],
    bonusTotalWin: ['total_win_1.mp3', 'total_win_2.mp3'],
    countLoop: ['count_loop_1.wav', 'count_loop_2.wav'], // 1 bar / 2 bars, gapless wav
  };
  for (const [key, files] of Object.entries(SUNO_SFX)) {
    const paths = files.map((f) => `${SUNO}${f}?p=1`);
    EVENTS[key].src.push(...paths);
    EVENTS[key].variant = paths[0];
    delete EVENTS[key].off;
  }

  // one-time: drop mixes saved in ♪ before the designer's mix became the
  // default, so every browser starts from it (later ♪ choices are kept)
  try {
    const MIX = '2026-11-24';
    if (localStorage.getItem('soundlab.great-uniqorn.mix') !== MIX) {
      localStorage.removeItem('soundlab.great-uniqorn');
      localStorage.setItem('soundlab.great-uniqorn.mix', MIX);
    }
  } catch (err) { /* storage blocked */ }

  const kit = SoundKit.create({
    game: 'great-uniqorn',
    sfxVolume: 0.18,
    musicVolume: 0.55,
    libraryPrefix: GAME,
    variantName: (path) => {
      const m = path && /\/sets\/([a-z]+)\//.exec(path);
      if (m) return `сет · ${SET_NAMES[m[1]] || m[1]}`;
      if (path && path.includes('/suno/')) { const n = /_(\d+)\.\w+/.exec(path); return n ? `Suno · дубль ${n[1]}` : 'Suno'; }
      return path && path.includes('/synth_v1/') ? 'синтез (старый)' : path && path.includes('/pack_loud/') ? 'пак композитора — громкий (первый)' : path && path.startsWith(GAME) ? 'пак композитора' : null;
    },
    sets: [{
      title: 'Звуковой сет',
      note: 'музыка базы и бонуса + все игровые звуки одним жанром (кнопки интерфейса общие); F — пак композитора',
      keys: SET_EVENTS,
      names: [...SET_KEYS.map((k) => SET_NAMES[k]), 'пак композитора'],
      count: SET_KEYS.length + 1,
      preview: () => (document.getElementById('screen') && document.getElementById('screen').dataset.mode === 'freespins' ? 'bonus' : 'base'),
    }],
    events: EVENTS,
  });

  // Set F (the composer's pack) has no file for a few events (count end,
  // anticipation hit / miss): on F they go silent, as before the sets, and
  // the panel still reads the set as F.
  const COMPOSER = SET_KEYS.length;
  const applySet = kit.lab.applySet;
  kit.lab.applySet = (si, vi) => {
    applySet(si, vi);
    if (si === 0 && vi === COMPOSER) for (const key of SET_EVENTS) if (!kit.lab.event(key).variants[vi]) kit.lab.setVariant(key, null);
  };
  const setVariantIndex = kit.lab.setVariantIndex;
  kit.lab.setVariantIndex = (si) => {
    const idx = setVariantIndex(si);
    if (idx >= 0 || si !== 0) return idx;
    const onF = SET_EVENTS.every((key) => {
      const e = kit.lab.event(key);
      return e.variants[COMPOSER] ? e.active === e.variants[COMPOSER] : e.off;
    });
    return onF ? COMPOSER : -1;
  };

  // --- ambience bed under the music ------------------------------------------
  let ambient = null;
  let ambientKey = null;
  // The beds belong to the composer's music: under a set (or the old synth)
  // they would clash, so they only run while that music is the composer's.
  const composerMusic = (lvl) => {
    const a = kit.lab.event(lvl === 'bonus' ? 'bonus' : 'base').active;
    return !!a && a.startsWith(GAME) && !a.includes('/sets/') && !a.includes('/synth_v1/') && !a.includes('/suno/');
  };
  function startAmbient(level) {
    const key = level === 'bonus' ? 'ambientBonus' : 'ambientBase';
    if (!composerMusic(level)) {
      if (ambient) { ambient.stop(400); ambient = null; ambientKey = null; }
      return;
    }
    if (ambient && ambientKey === key && !ambient.stopped) return;
    if (ambient) ambient.stop(400);
    ambientKey = key;
    ambient = kit.playSfx(key, { loop: true });
  }
  let level = 'base';
  let unlocked = false;

  // --- one melody at a time (2026-11-27, user: «ждать пока одно событие
  // закончится, потом после 0.5 секундной паузы начинать следующее») -------
  // Fanfares and stingers queue up: the next starts MELODY_GAP_MS after the
  // previous one ends, and the music under them steps back while one plays.
  // A music change asked for meanwhile cuts the old music at once and starts
  // the new one when the queue is quiet. Sound.whenQuiet() -> Promise lets
  // the game hold a popup until it may speak.
  const MELODY = new Set(['intro', 'symWin_scatter', 'fsWin', 'fsRetrigger', 'bigWin', 'megaWin', 'epicWin',
    'bonusTotalWin', 'baseToBonus', 'bonusToBase']);
  const MELODY_GAP_MS = 500;
  let melodyChain = Promise.resolve();
  let melodyPending = 0;
  const waitMs = (ms) => new Promise((res) => setTimeout(res, ms));
  function playMelody(key, opts) {
    const e = kit.lab.event(key);
    // nothing to hear: no slot in the queue, no pause
    if (!e || !e.active || e.muted || kit.isMuted()) return kit.playSfx(key, opts);
    let inner = null;
    let cancelled = false;
    let finish;
    const done = new Promise((res) => { finish = res; });
    melodyPending += 1;
    melodyChain = melodyChain.then(async () => {
      if (!cancelled) {
        const release = duck();
        inner = kit.playSfx(key, opts);
        await inner.done;
        release();
      }
      finish();
      await waitMs(cancelled ? 0 : MELODY_GAP_MS);
      melodyPending -= 1;
    });
    return {
      key,
      done,
      get stopped() { return cancelled || (inner && inner.stopped); },
      stop(fadeMs) { cancelled = true; if (inner) inner.stop(fadeMs); else finish(); },
    };
  }
  function playSfx(key, opts) {
    return MELODY.has(key) ? playMelody(key, opts) : kit.playSfx(key, opts);
  }
  const whenQuiet = () => melodyChain;

  let musicRequest = 0;
  function playMusic(key, opts) {
    level = key;
    const id = ++musicRequest;
    const start = () => {
      if (id !== musicRequest) return;
      kit.playMusic(key, melodyPending ? { ...(opts || {}), force: true } : opts);
      if (unlocked) startAmbient(key);
    };
    if (!melodyPending || !unlocked) { start(); return; }
    if (kit.lab.currentMusic() !== key) kit.stopMusic();
    melodyChain.then(start);
  }
  // the bed starts with the music on the first gesture (autoplay rules)
  // The intro (if it has a sound) plays first; the music starts when it ends.
  const unlock = () => {
    unlocked = true;
    const intro = kit.lab.event('intro');
    if (intro && intro.active && !kit.isMuted()) {
      kit.stopMusic();
      playMelody('intro').done.then(() => { kit.playMusic(level, { force: true }); startAmbient(level); });
      return;
    }
    startAmbient(level);
  };
  // switching the music variant in ♪ (one event or a whole set) re-checks
  // the bed; applySet goes through lab.setVariant too
  const setVariant = kit.lab.setVariant;
  kit.lab.setVariant = (key, path) => {
    setVariant(key, path);
    if (unlocked && (key === 'base' || key === 'bonus')) startAmbient(level);
  };
  window.addEventListener('pointerdown', unlock, { once: true });
  window.addEventListener('keydown', unlock, { once: true });

  // --- looping SFX (cash counter): returns stop() ---------------------------
  function startLoop(name) {
    const h = kit.playSfx(name, { loop: true });
    return () => h.stop(80);
  }

  function setMuted(value) {
    kit.setMuted(value);
    if (!value && unlocked) { ambient = null; startAmbient(level); }
  }

  // --- music ducking under the win popups (BIG/MEGA/EPIC, FS WIN, total) --
  // Sound.duck() lowers the music and returns release(); the music comes back
  // when the last holder releases.
  const DUCK_LEVEL = 0.3; // about -10 dB
  let duckHolders = 0;
  function duck() {
    duckHolders += 1;
    if (duckHolders === 1) kit.duckMusic(DUCK_LEVEL, 300);
    let released = false;
    return () => {
      if (released) return;
      released = true;
      duckHolders = Math.max(0, duckHolders - 1);
      if (!duckHolders) kit.duckMusic(1, 900);
    };
  }

  window.Sound = {
    duck,
    whenQuiet,
    playSfx,
    stopSfx: kit.stopSfx,
    playMusic,
    stopMusic: kit.stopMusic,
    startLoop,
    setMuted,
    toggleMuted: () => setMuted(!kit.isMuted()),
    isMuted: kit.isMuted,
    get muted() { return kit.isMuted(); },
    preloadPromises: kit.preloadPromises,
    lab: kit.lab,
  };
})();
